<main>
  <h1>Stale search results</h1>
  <label for="q">Search records</label>
  <input id="q">
  <button id="go">Search</button>
  <output id="status" role="status"></output>
  <p id="result"></p>
</main>
<script>
  // HumanCraft: Interaction & Verification
  // 1. Ground: Inspect existing state interface.
  // 2. Frame: The problem is that a slow search overwrites the latest query.
  //    We must preserve the latest query and status while processing.
  // 3. Explore: Use a state object to track the current query and the processing status.
  // 4. Specify:
  //    - Entry: User types query and clicks Search.
  //    - Action: Update state.query, set status to "Searching...", start timeout.
  //    - Outcome: On timeout, update state.result and result text.
  //    - Recovery: If user types again, update state.query immediately.
  //    - State Interface: window.readState() returns { query, result }.
  // 5. Build: Implement the logic.
  // 6. Challenge: Test rapid typing, slow vs fast queries.
  // 7. Verify: Ensure state is consistent.

  const field = document.getElementById("q");
  const go = document.getElementById("go");
  const out = document.getElementById("status");
  const result = document.getElementById("result");

  // State management: separate query from result to prevent overwriting
  let seq = 0;
  let state = {
    query: "",
    result: ""
  };

  // Helper to update UI safely
  function updateUI() {
    result.textContent = state.result;
    out.textContent = state.query ? `Results for ${state.query}` : "";
  }

  go.onclick = () => {
    const q = field.value;
    const n = ++seq;

    // Update the query immediately so it's preserved if a new search starts
    state.query = q;

    // Update status to indicate processing
    out.textContent = "Searching " + q;

    // Simulate network delay based on query content
    const delay = q === "alpha" ? 180 : 30;

    setTimeout(() => {
      // Only update result if this is the latest sequence number
      // This prevents slow searches from overwriting fast ones if the user types again
      if (n === seq) {
        state.result = q;
        updateUI();
      }
    }, delay);
  };

  // Allow updating state immediately on input change (optional UX improvement)
  field.oninput = () => {
    state.query = field.value;
    // Optional: Clear result immediately to show "live" typing state
    // if (field.value) {
    //   state.result = "";
    //   updateUI();
    // }
  };

  window.readState = () => state;
</script>
